WITH base AS MATERIALIZED(SELECT company_id,session_date,dated_anchor_point_and_source_value_link_verified ok,regular_session_basis_verified session_ok,corporate_action_qualified action_ok,independent_economic_accuracy_verified accuracy_ok FROM population_top3000_202608_202609_v1.working_d02_dated_source_points_v2),
corrections AS MATERIALIZED(SELECT company_id,session_date,dated_point_and_source_link_verified ok FROM population_top3000_202608_202609_v1.working_d02_sec_corroborated_points_v1 UNION ALL SELECT company_id,session_date,dated_point_and_source_link_verified FROM population_top3000_202608_202609_v1.working_d02_adig_corroborated_points_v1),
perday AS(SELECT b.session_date,count(*) base_rows,count(DISTINCT b.company_id) companies,count(*) FILTER(WHERE b.ok) original_verified_points,count(*) FILTER(WHERE NOT b.ok) original_held_points,count(*) FILTER(WHERE NOT b.ok AND c.ok) separate_corrections,count(*) FILTER(WHERE NOT b.ok AND c.ok IS DISTINCT FROM true) remaining_held_points,count(*) FILTER(WHERE session_ok AND action_ok AND accuracy_ok) economically_qualified_points FROM base b LEFT JOIN corrections c USING(company_id,session_date) GROUP BY b.session_date)
SELECT jsonb_build_object('observed_at',clock_timestamp(),'selected_company_count',(SELECT count(*) FROM population_top3000_202608_202609_v1.working_accepted_companies_v1),'original_grid_rows',(SELECT count(*) FROM base),'original_duplicate_company_dates',(SELECT count(*) FROM(SELECT company_id,session_date FROM base GROUP BY 1,2 HAVING count(*)>1)x),'correction_rows',(SELECT count(*) FROM corrections),'correction_duplicate_company_dates',(SELECT count(*) FROM(SELECT company_id,session_date FROM corrections GROUP BY 1,2 HAVING count(*)>1)x),'corrections_outside_original_grid',(SELECT count(*) FROM corrections c LEFT JOIN base b USING(company_id,session_date) WHERE b.company_id IS NULL),'sessions',(SELECT jsonb_agg(to_jsonb(p) ORDER BY session_date) FROM perday p),'breadth_reconciliation',(SELECT jsonb_build_object('sessions',count(*),'expected_company_count_mismatch',count(*) FILTER(WHERE expected_company_count<>3000),'vote_arithmetic_mismatch',count(*) FILTER(WHERE advancing+declining+unchanged<>valid_company_count OR valid_company_count+missing_company_count<>expected_company_count),'preliminary_valid_company_sessions',sum(valid_company_count),'preliminary_missing_company_sessions',sum(missing_company_count),'family_accepted_rows',count(*) FILTER(WHERE family_accepted)) FROM population_top3000_202608_202609_v1.working_breadth_preliminary_v1),'qualification','CURRENT_POPULATION_AND_CORRECTION_RECONCILIATION_NOT_ACTION_SESSION_OR_ECONOMIC_ACCEPTANCE') proof;
WITH votes AS MATERIALIZED(SELECT * FROM population_top3000_202608_202609_v1.ctx06_observed_vote_v4 WHERE run_key='a8b5b252d10b2a64bbe768ac7e9a51b013ecffa5600a948e3a86fa6b67598ba3'),
days AS(SELECT session_date,count(*) rows,count(DISTINCT company_id) companies,count(*) FILTER(WHERE return_1d>0) advancing,count(*) FILTER(WHERE return_1d<0) declining,count(*) FILTER(WHERE return_1d=0) unchanged,count(*) FILTER(WHERE return_1d IS NULL) missing FROM votes GROUP BY session_date)
SELECT jsonb_build_object('vote_rows',(SELECT count(*) FROM votes),'duplicate_company_dates',(SELECT count(*) FROM(SELECT company_id,session_date FROM votes GROUP BY 1,2 HAVING count(*)<>1)x),'unselected_company_rows',(SELECT count(*) FROM votes v LEFT JOIN population_top3000_202608_202609_v1.working_accepted_companies_v1 a ON a.company_id=v.company_id WHERE a.company_id IS NULL),'missing_reason_counts',(SELECT jsonb_object_agg(reason,n) FROM(SELECT coalesce(missing_reason,'VALUE') reason,count(*) n FROM votes GROUP BY 1)x),'days',(SELECT jsonb_agg(to_jsonb(d) ORDER BY session_date) FROM days d),'aggregate_vs_vote_mismatches',(SELECT count(*) FROM days d JOIN population_top3000_202608_202609_v1.working_breadth_preliminary_v1 s USING(session_date) WHERE d.advancing<>s.advancing OR d.declining<>s.declining OR d.unchanged<>s.unchanged OR d.missing<>s.missing_company_count),'vote_digest',(SELECT encode(sha256(convert_to(string_agg(record_sha256,chr(10) ORDER BY session_date,company_ordinal),'UTF8')),'hex') FROM votes)) proof;